parts.text:
{
  "tom_tat": "Hệ thống phân loại mô hình đã dự đoán mẫu thuộc lớp DDoS với mức xác suất cao và vượt trội hoàn toàn so với lớp đứng thứ hai là DoS. Các đặc trưng trong top năm đều đóng vai trò hỗ trợ nâng cao đầu ra của lớp này so với giá trị nền tham chiếu.",
  "lop_du_doan": "DDoS",
  "so_sanh_hai_lop": {
    "lop_thu_hai": "DoS",
    "khoang_cach_nho": false,
    "dien_giai": "Cờ khoảng cách nhỏ đang tắt vì chênh lệch giữa hai đầu ra lớn, nhưng việc này không bảo đảm dự đoán chắc chắn đúng do chưa có nhãn thật."
  },
  "tong_hop_shap": {
    "ho_tro_manh_nhat": "IAT",
    "phan_doi_manh_nhat": null,
    "dien_giai": "Đặc trưng IAT là yếu tố hỗ trợ mạnh nhất đẩy đầu ra tăng lên, trong khi không có yếu tố nào trong top năm tạo ra tác động phản đối mang giá trị âm."
  },
  "giai_thich_dac_trung": [
    {
      "ten_dac_trung": "IAT",
      "huong_tac_dong": "tang",
      "dien_giai": "Đây là yếu tố hỗ trợ nổi bật nhất trong top năm, đóng góp mức tăng lớn nhất vào điểm số của lớp dự đoán."
    },
    {
      "ten_dac_trung": "Protocol Type",
      "huong_tac_dong": "tang",
      "dien_giai": "Đặc trưng này cung cấp sự hỗ trợ bổ sung cùng chiều với mức tác động nhỏ hơn vị trí dẫn đầu."
    },
    {
      "ten_dac_trung": "Magnitue",
      "huong_tac_dong": "tang",
      "dien_giai": "Sự đóng góp dương tiếp tục xuất hiện với biên độ thấp hơn để đẩy giá trị đầu ra lên."
    },
    {
      "ten_dac_trung": "Min",
      "huong_tac_dong": "tang",
      "dien_giai": "Đặc trưng này mang lại một mức tác động dương nhỏ trong nhóm năm yếu tố hàng đầu."
    },
    {
      "ten_dac_trung": "Number",
      "huong_tac_dong": "tang",
      "dien_giai": "Đây là yếu tố có đóng góp dương nhỏ nhất trong top năm đặc trưng được liệt kê."
    }
  ],
  "de_xuat_kiem_tra": [
    {
      "nguon_du_lieu": "Nhật ký lưu lượng mạng",
      "noi_dung_can_kiem_tra": "Kiểm tra sự đồng thời của nhiều nguồn đến cùng dịch vụ nếu có địa chỉ và thời gian",
      "muc_dich": "Đối chiếu đặc trưng lưu lượng với diễn biến thực tế trên hệ thống mạng nếu hệ thống có lưu trữ nhật ký này."
    },
    {
      "nguon_du_lieu": "Nhật ký tài nguyên dịch vụ",
      "noi_dung_can_kiem_tra": "Đối chiếu lưu lượng với tình trạng tài nguyên và khả năng phục vụ, không tự đặt ngưỡng",
      "muc_dich": "Kiểm tra khả năng chịu tải và phản ứng của hệ thống nhằm bổ sung bằng chứng đối chiếu nếu có log tài nguyên."
    }
  ],
  "gioi_han": [
    "Giá trị SHAP chỉ giải thích đầu ra của mô hình đối với mẫu này và không chứng minh được quan hệ nhân quả hay hành vi tấn công thực tế.",
    "Xác suất dự đoán chưa được kiểm chứng hay hiệu chỉnh độ tin cậy tuyệt đối.",
    "Tổng các giá trị SHAP trong top năm chưa phải toàn bộ sự thay đổi vì vẫn còn phần đóng góp từ các đặc trưng nằm ngoài nhóm."
  ]
}

